defaults: { ease: 'none' },
scrollTrigger: {
trigger: pinEl,
start: () => `top top+=${offset()}`,
end: () => `+=${Math.round((cards.length - 1) * window.innerHeight * 0.85)}`,
pin: true,
scrub: 0.6,
anticipatePin: 1,
invalidateOnRefresh: true,
},
